// Uses one real UAC request for the privileged half; tool execution stays under
// the invoking user's token. All content fixtures are generated by this script.
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { mkdir, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { configureWindowsSandbox, windowsSandboxHelper, windowsSandboxStatus } from "../src-tauri/runtime/windows-sandbox.mjs";
import { createExecutor } from "../src-tauri/runtime/execution.mjs";

const exec=promisify(execFile),base=resolve(".tao-release-cache/windows-executor-lab");await mkdir(base,{recursive:true});
const root=await mkdtemp(join(base,"setup-run-")),project=join(root,"project"),home=join(root,"home");
await mkdir(project);await mkdir(home);configureWindowsSandbox(home);
const helper=windowsSandboxHelper(),shell=join(process.env.SystemRoot,"System32/WindowsPowerShell/v1.0/powershell.exe"),checks=[];
const waitFor=async(name)=>{const until=Date.now()+90000;while(Date.now()<until){try{return JSON.parse(await readFile(join(root,name),'utf8'));}catch(error){if(error.code!=='ENOENT'&&!(error instanceof SyntaxError))throw error;}await new Promise(done=>setTimeout(done,80));}throw new Error(`timeout: ${name}`);};
const worker=join(root,"setup-worker.ps1");
await writeFile(worker,`param([string]$Helper,[string]$Fixture,[string]$Workspace)
$ErrorActionPreference='Stop'
function Save-Result([string]$Name, [object]$Value) { [IO.File]::WriteAllText((Join-Path $Fixture $Name),($Value | ConvertTo-Json -Compress -Depth 10)) }
function Wait-Fixture([string]$Name) { $deadline=[DateTime]::UtcNow.AddSeconds(90); while(-not [IO.File]::Exists((Join-Path $Fixture $Name))) {if([DateTime]::UtcNow -gt $deadline){throw 'controller timeout'};Start-Sleep -Milliseconds 100} }
$result=& $Helper --compat-cleanup 2>&1; $code=$LASTEXITCODE
Save-Result 'blocked.json' @{exitCode=$code;output=($result -join '\n')}
Wait-Fixture 'go-remove'
$result=& $Helper --compat-cleanup 2>&1; $code=$LASTEXITCODE
Save-Result 'removed.json' @{exitCode=$code;output=($result -join '\n')}
Wait-Fixture 'go-prepare'
$result=& $Helper --compat-prepare --metadata-path $Workspace 2>&1; $code=$LASTEXITCODE
Save-Result 'prepared.json' @{exitCode=$code;output=($result -join '\n')}
exit $code
`);
let controller=new AbortController(),readyResolve;const ready=new Promise(done=>readyResolve=done);
let task,setup;
try {
  assert((await windowsSandboxStatus(project)).available,'prepare native backend before this suite');
  task=createExecutor({backend:'windows'},project).execute('node',['-e',"console.log('LEASE_READY');setInterval(()=>{},1000)"],{signal:controller.signal,onData:data=>{if(data.toString().includes('LEASE_READY'))readyResolve();}});
  task.catch(()=>{});await ready;
  setup=exec(shell,['-NoProfile','-NonInteractive','-Command',"$p=Start-Process -FilePath $env:TAO_UAC_SHELL -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',('\"'+$env:TAO_UAC_WORKER+'\"'),'-Helper',('\"'+$env:TAO_UAC_HELPER+'\"'),'-Fixture',('\"'+$env:TAO_UAC_FIXTURE+'\"'),'-Workspace',('\"'+$env:TAO_UAC_WORKSPACE+'\"')) -Verb RunAs -WindowStyle Hidden -Wait -PassThru;exit $p.ExitCode"],{windowsHide:true,timeout:120000,env:{...process.env,TAO_UAC_SHELL:shell,TAO_UAC_WORKER:worker,TAO_UAC_HELPER:helper,TAO_UAC_FIXTURE:root,TAO_UAC_WORKSPACE:base}});
  setup.catch(()=>{});
  const blocked=await waitFor('blocked.json');assert.notEqual(blocked.exitCode,0);assert.match(blocked.output,/lease unavailable/);assert((await windowsSandboxStatus(project)).available);checks.push('active execution blocks privileged removal without changing readiness');
  controller.abort();await assert.rejects(task,/取消|超时/);task=undefined;
  await writeFile(join(root,'go-remove'),'go');const removed=await waitFor('removed.json');assert.equal(removed.exitCode,0,removed.output);assert.equal((await windowsSandboxStatus(project)).available,false);checks.push('explicit removal succeeds after cancellation and status becomes unavailable');
  await assert.rejects(createExecutor({backend:'windows'},project).execute('node',['-e',"require('fs').writeFileSync('must-not-run','bad')"]),/未回退/);checks.push('removed backend cannot silently execute on host');
  await writeFile(join(root,'go-prepare'),'go');const prepared=await waitFor('prepared.json');assert.equal(prepared.exitCode,0,prepared.output);await setup;assert((await windowsSandboxStatus(project)).available);checks.push('administrator reinitialization restores ready state');
  const result=await createExecutor({backend:'windows'},project).execute('node',['-e',"console.log('RESTORED')"]);assert.match(result.stdout,/RESTORED/);checks.push('real tool runs after reinitialization');
  await writeFile(join(root,'report.json'),JSON.stringify({root,checks,passed:checks.length,realUac:true,rebootValidated:false,windows10Validated:false},null,2));console.log(JSON.stringify({root,checks,passed:checks.length}));
} catch(error) {
  controller.abort();await task?.catch(()=>{});
  // Always release the privileged worker and restore setup if a fixture assertion fails.
  await writeFile(join(root,'go-remove'),'go');await writeFile(join(root,'go-prepare'),'go');await setup?.catch(()=>{});
  await writeFile(join(root,'report.json'),JSON.stringify({root,checks,failure:String(error.stack||error)},null,2));throw error;
}
